#include <LVRS/HierarchyProjection.h>
#include <algorithm>
#include <cmath>
#include <iostream>
#include <random>
#include <stdexcept>
#include <thread>
#include <type_traits>
using namespace ii;
using namespace lvrs;
static_assert(!std::is_copy_constructible_v<HierarchyProjection>&&!std::is_move_constructible_v<HierarchyProjection>);
namespace {
void check(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
template<class T>T take(core::Result<T> value){if(!value)throw std::runtime_error(value.error().message);return std::move(*value);}
void good(core::Result<void> value){if(!value)throw std::runtime_error(value.error().message);}
std::vector<HierarchyRow> fixture(){return {{.key="a",.label="Root",.expanded=true},{.key="b",.label="Branch",.depth=1,.expanded=true},{.key="c",.label="Leaf",.depth=2},{.key="d",.label="Disabled",.depth=1,.enabled=false},{.key="e",.label="Other"},{.key="f",.label="Hidden",.depth=1},{.key="g",.label="Inactive",.activatable=false}};}
void compare(const std::shared_ptr<HierarchyModel>& model,const std::shared_ptr<HierarchyProjection>& view){
    auto rows=take(model->rows());std::vector<std::size_t> visible,eligible;std::vector<std::size_t> ancestors;
    std::vector<double> starts(rows.size());double extent=0;
    for(std::size_t i=0;i<rows.size();++i){
        while(ancestors.size()>rows[i].depth)ancestors.pop_back();bool show=true;
        for(auto a:ancestors)if(rows[a].show_chevron&&!take(view->expanded(a)))show=false;
        check(take(view->visible(i))==show,"Range index differs from independent ancestor visibility oracle");starts[i]=extent;
        if(show){check(take(view->visible_rank(i))==visible.size(),"Visible rank differs");visible.push_back(i);if(rows[i].enabled&&rows[i].activatable)eligible.push_back(i);extent+=take(view->row_extent(i));}
        ancestors.push_back(i);
    }
    auto state=take(view->state());check(state.count==rows.size()&&state.visible_count==visible.size()&&state.eligible_count==eligible.size()&&std::abs(state.content_extent-extent)<.001,"Visibility aggregate differs from oracle");
    for(std::size_t rank=0;rank<visible.size();++rank){auto i=visible[rank];check(take(view->at_visible(rank))==i&&std::abs(take(view->offset(i))-starts[i])<.001,"Rank/extent selection differs");check(take(view->at_offset(starts[i]+take(view->row_extent(i))*.5))==i,"Variable-height hit test differs");}
    for(std::size_t rank=0;rank<eligible.size();++rank)check(take(view->at_eligible(rank))==eligible[rank]&&take(view->eligible_rank(eligible[rank]))==rank,"Keyboard eligibility rank differs");
    check(!view->at_visible(visible.size())&&!view->at_eligible(eligible.size())&&!view->at_offset(extent),"Out-of-range projection query accepted");
}
void run(const std::string& name){
    auto model=take(HierarchyModel::create());take(model->set_rows(fixture()));auto view=take(HierarchyProjection::create(model));
    if(name=="defaults"){auto state=take(view->state());check(state.visible_count==6&&state.eligible_count==4&&state.content_extent==120,"Default projection changed");compare(model,view);}
    else if(name=="empty"){take(model->set_rows({}));compare(model,view);check(!take(view->expand_all())&&!take(view->collapse_all()),"Empty bulk operation mutated view");}
    else if(name=="options"){check(!HierarchyProjection::create({})&&!HierarchyProjection::create(model,{.row_extent=0})&&!HierarchyProjection::create(model,{.row_extent=std::numeric_limits<double>::infinity()}),"Invalid projection options accepted");check(!HierarchyProjection::create(model,{.maximum_rows=1}),"Projection row admission ignored");}
    else if(name=="collapse"||name=="expand"){take(view->set_expanded(0,false));check(take(view->state()).visible_count==3,"Ancestor collapse did not cover descendants");if(name=="expand"){take(view->set_expanded(0,true));check(take(view->state()).visible_count==6,"Ancestor expand lost descendant expansion");}compare(model,view);}
    else if(name=="nested"){take(view->set_expanded(0,false));take(view->set_expanded(1,false));take(view->set_expanded(0,true));check(!take(view->visible(2))&&take(view->visible(1)),"Nested collapsed coverage was lost");take(view->set_expanded(1,true));compare(model,view);}
    else if(name=="no_chevron"){auto row=take(model->row(0)).get();row.expanded=false;row.show_chevron=false;take(model->update_row("a",row));check(take(view->visible(1)),"Hidden chevron suppressed children");take(view->set_expanded(0,false));compare(model,view);}
    else if(name=="data"){auto row=take(model->row(2)).get();auto before=take(view->state());row.label="New";take(model->update_row("c",row));auto after=take(view->state());check(after.topology_resets==before.topology_resets&&after.range_updates==before.range_updates,"Label edit rebuilt visibility topology");row.enabled=false;take(model->update_row("c",row));compare(model,view);}
    else if(name=="source_expansion"){auto row=take(model->row(4)).get();row.expanded=true;take(model->update_row("e",row));check(take(view->visible(5)),"Source default expansion change was not observed");take(view->set_expanded(4,false));row.expanded=false;take(model->update_row("e",row));row.expanded=true;take(model->update_row("e",row));check(!take(view->visible(5)),"View-local override was replaced by model default");compare(model,view);}
    else if(name=="ancestors"){take(view->set_expanded(0,false));take(view->set_expanded(1,false));auto revision=take(model->state()).revision;check(take(view->expand_ancestors(2))&&take(view->visible(2))&&take(model->state()).revision==revision,"Ancestor expansion changed model data");compare(model,view);}
    else if(name=="bulk"){take(view->expand_all());check(take(view->state()).visible_count==7,"Expand all missed a branch");take(view->collapse_all());check(take(view->visible(1))&&!take(view->visible(2))&&take(view->visible(5)),"Default collapse-all did not preserve roots");take(view->collapse_all(false));check(take(view->state()).visible_count==3,"Collapse-all(false) kept descendants");compare(model,view);}
    else if(name=="height"){take(view->set_row_extent(0,31));take(view->set_row_extent(2,51));check(take(view->at_offset(31))==1&&take(view->at_offset(51))==2,"Variable-height boundary mapping changed");take(view->set_expanded(0,false));take(view->set_row_extent(2,99));take(view->set_expanded(0,true));compare(model,view);}
    else if(name=="invalid"){check(!view->set_row_extent(0,0)&&!view->set_row_extent(0,std::numeric_limits<double>::quiet_NaN())&&!view->set_expanded(99,true)&&!view->at_offset(-1)&&!view->at_offset(std::numeric_limits<double>::infinity()),"Invalid projection query/mutation admitted");compare(model,view);}
    else if(name=="fault_recovery"){view=take(HierarchyProjection::create(model,{.maximum_rows=7}));auto data=fixture();data.push_back({.key="extra"});auto changed=model->set_rows(data);check(!changed&&take(model->state()).count==8&&take(view->state()).faulted&&!view->offset(0),"Projection admission failure hid a committed source or exposed stale index");take(model->set_rows(fixture()));check(!take(view->state()).faulted,"Projection did not recover after source admission became valid");compare(model,view);}
    else if(name=="pending_source"){good(view->close());bool rejected=false;auto first=std::make_shared<HierarchyChangePort>([&](const auto& change){if(change.kind!=HierarchyChangeKind::data)return;auto result=view->offset(0);rejected=!result&&result.error().code==core::ErrorCode::busy;});good(model->observe(first));view=take(HierarchyProjection::create(model));auto row=take(model->row(2)).get();row.label="New";take(model->update_row("c",row));check(rejected,"Projection queried stale indices before receiving source revision");compare(model,view);(void)first->close();}
    else if(name=="metadata"){auto m=take(view->metadata(0));check(m.visible&&m.visible_index==0&&m.visible_child_count==2&&m.visible_descendant_count==3,"Visible metadata is wrong");take(view->set_expanded(1,false));m=take(view->metadata(0));check(m.visible_descendant_count==2,"Collapsed descendant metadata is wrong");m=take(view->metadata(2));check(!m.visible&&!m.visible_index&&m.visible_sibling_count==0,"Hidden row metadata invented visibility");}
    else if(name=="isolation"){auto other=take(HierarchyProjection::create(model));auto revision=take(model->state()).revision;take(view->set_expanded(0,false));take(view->set_row_extent(4,31));check(take(other->visible(2))&&take(other->row_extent(4))==20&&take(model->state()).revision==revision,"Shared source leaked view state or became dirty");}
    else if(name=="structural"){take(view->set_expanded(4,true));take(view->set_row_extent(4,31));auto plan=take(model->plan_move("e",0,0));take(model->commit_move(plan));auto i=take(model->index_of_key("e"));check(i==0&&take(view->expanded(i))&&take(view->row_extent(i))==31,"Structural move lost key-based local state");compare(model,view);}
    else if(name=="reset"){take(view->set_expanded(4,true));auto data=fixture();data.erase(data.begin(),data.begin()+4);take(model->set_rows(data));check(take(view->expanded(0))&&take(view->visible(1)),"Reset lost surviving key expansion");take(model->set_rows({}));take(model->set_rows(fixture()));check(!take(view->expanded(4)),"Removed identity retained stale override");compare(model,view);}
    else if(name=="nonmutation"){auto source=take(model->state());auto before=take(model->stats());for(unsigned i=0;i<100;++i){take(view->set_expanded(0,i%2));take(view->set_row_extent(4,20+i%2));take(view->offset(4));}auto after=take(model->stats());check(take(model->state()).revision==source.revision&&after.topology_builds==before.topology_builds&&after.metadata_queries==before.metadata_queries,"View interaction rebuilt/mutated source metadata");}
    else if(name=="observe"||name=="weak"||name=="dedup"){unsigned count=0;auto port=std::make_shared<HierarchyProjectionPort>([&](const auto& c){++count;check(c.state.revision==take(view->state()).revision,"Projection notification is stale");});good(view->observe(port));if(name=="dedup")good(view->observe(port));if(name=="weak")port.reset();take(view->set_expanded(0,false));check(count==(name=="weak"?0u:1u),"Projection weak/dedup observation failed");if(port)(void)port->close();}
    else if(name=="reentrant"){bool rejected=false;auto port=std::make_shared<HierarchyProjectionPort>([&](const auto&){auto result=view->set_expanded(0,true);rejected=!result&&result.error().code==core::ErrorCode::busy;});good(view->observe(port));take(view->set_expanded(0,false));check(rejected&&!take(view->expanded(0)),"Projection notification allowed reentry");(void)port->close();}
    else if(name=="fanout"){unsigned healthy=0;auto bad=std::make_shared<HierarchyProjectionPort>([](const auto&){throw std::runtime_error("receiver");});auto port=std::make_shared<HierarchyProjectionPort>([&](const auto&){++healthy;});good(view->observe(bad));good(view->observe(port));auto result=view->set_expanded(0,false);check(!result&&healthy==1&&!take(view->state()).faulted&&!take(view->expanded(0)),"Observer failure corrupted committed projection state");auto row=take(model->row(2)).get();row.label="New";auto updated=model->update_row("c",row);check(!updated&&healthy==2&&!take(view->state()).faulted&&take(view->state()).model_revision==take(model->state()).revision,"Source fanout failure left projection stale");(void)bad->close();(void)port->close();}
    else if(name=="closed"||name=="source_closed"){unsigned closed=0;auto port=std::make_shared<HierarchyProjectionPort>([&](const auto& c){if(c.state.closed)++closed;});good(view->observe(port));if(name=="closed")good(view->close());else good(model->close());good(view->close());check(closed==1&&take(view->state()).closed&&!view->visible(0)&&!view->set_expanded(0,true),"Closed projection admitted work or delivered twice");(void)port->close();}
    else if(name=="close_in_notify"){unsigned closed=0;auto first=std::make_shared<HierarchyProjectionPort>([&](const auto& c){if(!c.state.closed)good(view->close());});auto last=std::make_shared<HierarchyProjectionPort>([&](const auto& c){if(c.state.closed)++closed;else throw std::runtime_error("stale");});good(view->observe(first));good(view->observe(last));take(view->set_expanded(0,false));check(closed==1,"Projection terminal notification was lost during reentry");(void)first->close();(void)last->close();}
    else if(name=="lifetime"){auto raw=view.get();bool released=false;auto port=std::make_shared<HierarchyProjectionPort>([&](const auto& c){if(!c.state.closed){view.reset();released=true;}});good(view->observe(port));take(raw->set_expanded(0,false));check(released&&!view,"Public projection release during delivery was unsafe");(void)port->close();}
    else if(name=="owner"){bool rejected=false;std::thread worker([&]{auto a=view->state(),b=view->state();auto c=view->set_expanded(0,false);rejected=!a&&!b&&!c&&c.error().code==core::ErrorCode::wrong_executor;});worker.join();check(rejected,"Wrong owner accessed projection");compare(model,view);}
    else if(name=="large"){std::vector<HierarchyRow> data;for(std::size_t i=0;i<100000;++i)data.push_back({.key=std::to_string(i),.depth=std::uint32_t(i?1:0)});take(model->set_rows(std::move(data)));auto before=take(view->state());auto source=take(model->state());for(unsigned i=0;i<1000;++i)take(view->set_expanded(0,i%2==0));auto after=take(view->state());check(after.topology_resets==before.topology_resets&&after.range_updates-before.range_updates==1000&&take(model->state()).revision==source.revision&&after.visible_count==1,"Branch toggles rebuilt tree or mutated data");}
    else if(name=="random"){std::mt19937 random(223);for(unsigned i=0;i<700;++i){auto index=random()%7;switch(i%5){case 0:take(view->set_expanded(index,random()%2));break;case 1:take(view->set_row_extent(index,8+random()%73));break;case 2:{auto row=take(model->row(index)).get();row.enabled=!row.enabled;take(model->update_row(row.key,row));break;}case 3:{auto row=take(model->row(index)).get();row.show_chevron=!row.show_chevron;take(model->update_row(row.key,row));break;}default:take(view->expand_ancestors(index));}compare(model,view);}}
    else throw std::runtime_error("Unknown hierarchy projection case");
}
}
int main(int argc,char** argv){try{run(argc>1?argv[1]:"defaults");std::cout<<"HIERARCHY_PROJECTION_OK\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
